import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.Property;
import net.minecraft.world.phys.Vec3;

public class BeltGrinderScenes {
    public static void processing(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("belt_grinder_processing", "Processing Items on the Belt Grinder");
        scene.configureBasePlate(0, 0, 5);
        scene.world().showSection(util.select().layer(0), Direction.UP);
        BlockPos shaftPos = util.grid().at(2, 1, 3);
        scene.world().setBlock(shaftPos, (BlockState)AllBlocks.SHAFT.getDefaultState().m_61124_((Property)ShaftBlock.AXIS, (Comparable)Direction.Axis.Z), false);
        BlockPos grinderPos = util.grid().at(2, 1, 2);
        Selection grinderSelect = util.select().position(grinderPos);
        scene.world().modifyBlockEntityNBT(grinderSelect, GrinderBlockEntity.class, nbt -> nbt.m_128405_("RecipeIndex", 0));
        scene.idle(5);
        scene.world().showSection(util.select().fromTo(2, 1, 3, 2, 1, 5), Direction.DOWN);
        scene.idle(10);
        scene.effects().rotationDirectionIndicator(shaftPos);
        scene.world().showSection(grinderSelect, Direction.DOWN);
        scene.idle(10);
        scene.overlay().showText(50).attachKeyFrame().text("Belt Grinders can process a variety of items").pointAt(util.vector().blockSurface(grinderPos, Direction.WEST)).placeNearTarget();
        scene.idle(45);
        ItemStack quartz = new ItemStack((ItemLike)AllItems.ROSE_QUARTZ);
        ItemStack polished = new ItemStack((ItemLike)AllItems.POLISHED_ROSE_QUARTZ);
        Vec3 itemSpawn = util.vector().centerOf(grinderPos.m_7494_().m_122024_());
        ElementLink quartzItem = scene.world().createItemEntity(itemSpawn, util.vector().of(0.0, 0.0, 0.0), quartz);
        scene.idle(12);
        scene.overlay().showControls(itemSpawn, Pointing.DOWN, 20).withItem(quartz);
        scene.idle(10);
        scene.world().modifyEntity(quartzItem, e -> e.m_20256_(util.vector().of(0.05, 0.2, 0.0)));
        scene.idle(12);
        scene.world().modifyEntity(quartzItem, Entity::m_146870_);
        scene.world().createItemOnBeltLike(grinderPos, Direction.WEST, quartz);
        scene.idle(35);
        quartzItem = scene.world().createItemEntity(util.vector().topOf(grinderPos).m_82520_(0.5, -0.1, 0.0), util.vector().of(0.05, 0.18, 0.0), polished);
        scene.idle(12);
        scene.overlay().showControls(itemSpawn.m_82520_(2.0, 0.0, 0.0), Pointing.DOWN, 20).withItem(polished);
        scene.idle(30);
        scene.overlay().showText(60).attachKeyFrame().text("The processed item always moves against the rotational input to the grinder").pointAt(util.vector().blockSurface(grinderPos, Direction.UP)).placeNearTarget();
        scene.idle(70);

