public class CurvingPressScenes {
    public static void processing(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("curving_press", "Processing Items with the Curving Press");
        scene.configureBasePlate(0, 0, 5);
        scene.world().showSection(util.select().layer(0), Direction.UP);
        scene.idle(5);
        ElementLink depot = scene.world().showIndependentSection(util.select().position(2, 1, 1), Direction.DOWN);
        scene.world().moveSection(depot, util.vector().of(0.0, 0.0, 1.0), 0);
        scene.idle(10);
        Selection pressS = util.select().position(2, 3, 2);
        BlockPos pressPos = util.grid().at(2, 3, 2);
        BlockPos depotPos = util.grid().at(2, 1, 1);
        scene.world().setKineticSpeed(pressS, 0.0f);
        scene.world().showSection(pressS, Direction.DOWN);
        scene.idle(10);
        scene.world().showSection(util.select().fromTo(2, 1, 3, 2, 1, 5), Direction.NORTH);
        scene.idle(3);
        scene.world().showSection(util.select().position(2, 2, 3), Direction.SOUTH);
        scene.idle(3);
        scene.world().showSection(util.select().position(2, 3, 3), Direction.NORTH);
        scene.world().setKineticSpeed(pressS, -32.0f);
        scene.effects().indicateSuccess(pressPos);
        scene.idle(10);
        Vec3 pressSide = util.vector().blockSurface(pressPos, Direction.WEST);
        scene.overlay().showText(60).pointAt(pressSide).placeNearTarget().attachKeyFrame().text("Before work you must install any Curving Head to Curving Press");
        scene.idle(50);
        ItemStack head = new ItemStack((ItemLike)VintageItems.W_SHAPED_CURVING_HEAD.m_5456_());
        scene.overlay().showControls(util.vector().blockSurface(pressPos, Direction.NORTH), Pointing.RIGHT, 8).rightClick().withItem(head);
        scene.idle(8);
        scene.world().modifyBlockEntity(pressPos, CurvingPressBlockEntity.class, ms -> {
            ms.mode = 3;
        });
        scene.idle(12);
        scene.overlay().showText(60).pointAt(pressSide).placeNearTarget().attachKeyFrame().text("Different heads provides different recipes");
        scene.idle(70);
        scene.overlay().showText(60).pointAt(pressSide).placeNearTarget().attachKeyFrame().text("To remove head, you must right-click with a Wrench");

