import net.createmod.ponder.api.scene.SceneBuildingUtil;
import net.createmod.ponder.api.scene.Selection;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.ItemLike;
import net.minecraft.world.phys.Vec3;

public class VibratingTableScenes {
    public static void processing(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("vibrating_table", "Processing Items on the Vibrating Table");
        scene.configureBasePlate(0, 0, 5);
        Selection belt = util.select().fromTo(1, 1, 5, 0, 1, 2).add(util.select().position(1, 2, 2));
        Selection beltCog = util.select().position(2, 0, 5);
        scene.world().showSection(util.select().layer(0).substract(beltCog), Direction.UP);
        BlockPos table = util.grid().at(2, 2, 2);
        Selection tableSelect = util.select().position(2, 2, 2);
        Selection cogs = util.select().fromTo(3, 1, 2, 5, 2, 2);
        scene.world().setKineticSpeed(tableSelect, 0.0f);
        scene.idle(5);
        scene.world().showSection(util.select().position(4, 1, 3), Direction.DOWN);
        scene.world().showSection(util.select().position(2, 1, 2), Direction.DOWN);
        scene.idle(10);
        scene.world().showSection(util.select().position(table), Direction.DOWN);
        scene.idle(10);
        Vec3 tableTop = util.vector().topOf(table);
        scene.overlay().showText(40).attachKeyFrame().text("Vibrating Table can process a variety of items").pointAt(tableTop).placeNearTarget();
        scene.idle(50);
        scene.overlay().showText(40).attachKeyFrame().text("Also Vibrating Table can unpack storage blocks").pointAt(tableTop).placeNearTarget();
        scene.idle(50);
        scene.overlay().showText(40).attachKeyFrame().text("Or vibrate leaves to get matched drops, the chances are the same as using hoe with Fortune III").pointAt(tableTop).placeNearTarget();
        scene.idle(50);
        scene.world().showSection(cogs, Direction.DOWN);
        scene.idle(10);
        scene.world().setKineticSpeed(tableSelect, -100.0f);
        scene.effects().indicateSuccess(table);
        scene.idle(10);
        scene.overlay().showText(40).attachKeyFrame().colored(PonderPalette.GREEN).text("They can be powered from the side using shafts").pointAt(util.vector().topOf(table.m_122029_())).placeNearTarget();
        scene.idle(50);
        ItemStack itemStack = new ItemStack((ItemLike)Items.f_41913_);
        Vec3 entitySpawn = util.vector().topOf(table.m_6630_(3));
        ElementLink entity1 = scene.world().createItemEntity(entitySpawn, util.vector().of(0.0, 0.2, 0.0), itemStack);
        scene.idle(18);
        scene.world().modifyEntity(entity1, Entity::m_146870_);

